create type public.user_role as enum ('CUSTOMER','STAFF','ADMIN');
create type public.appointment_status as enum ('BOOKED','CONFIRMED','COMPLETED','CANCELLED');
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text not null, email text unique not null, phone text, role public.user_role not null default 'CUSTOMER', created_at timestamptz default now());
create table public.services (id uuid primary key default gen_random_uuid(), name text not null, description text, category text not null, price numeric(10,2) not null check(price >= 0), duration_minutes int not null check(duration_minutes > 0), required_skill text, is_active boolean default true, created_at timestamptz default now());
create table public.staff (id uuid primary key default gen_random_uuid(), profile_id uuid unique references public.profiles(id) on delete cascade, specialization text, is_active boolean default true, created_at timestamptz default now());
create table public.staff_services (id uuid primary key default gen_random_uuid(), staff_id uuid references public.staff(id) on delete cascade, service_id uuid references public.services(id) on delete cascade, unique(staff_id,service_id));
create table public.working_hours (id uuid primary key default gen_random_uuid(), staff_id uuid references public.staff(id) on delete cascade, day_of_week int check(day_of_week between 0 and 6), start_time time not null, end_time time not null, is_available boolean default true, unique(staff_id,day_of_week));
create table public.appointments (id uuid primary key default gen_random_uuid(), customer_id uuid references public.profiles(id), staff_id uuid references public.staff(id), service_id uuid references public.services(id), appointment_date date not null, start_time time not null, end_time time not null, status public.appointment_status default 'BOOKED', notes text, created_at timestamptz default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, message text not null, is_read boolean default false, created_at timestamptz default now());
create index appointments_staff_date_idx on public.appointments(staff_id, appointment_date); create index appointments_customer_idx on public.appointments(customer_id); create index appointments_status_idx on public.appointments(status);
alter table public.profiles enable row level security; alter table public.appointments enable row level security;
create policy "profiles own read" on public.profiles for select using (auth.uid()=id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='ADMIN'));
create policy "customers own appointments" on public.appointments for select using (auth.uid()=customer_id or auth.uid()=(select profile_id from public.staff where id=staff_id) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='ADMIN'));
create policy "customers create appointments" on public.appointments for insert with check (auth.uid()=customer_id);
create policy "customers cancel own" on public.appointments for update using (auth.uid()=customer_id or auth.uid()=(select profile_id from public.staff where id=staff_id) or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='ADMIN'));
